import type { ICtx, ScheduleHandle } from "@threenative/core";
import { CollisionShape3D, type IPhysicsContext, RigidBody3D } from "@threenative/physics";
import { type Group, Vector3 } from "three";
import { directSpaceState } from "../physics.js";
import { createRiflemanVisual } from "../render/shapes.js";
import type { GameState } from "../state.js";
import { HOSTILE_LAYER, PLAYER_LAYER, WORLD_LAYER } from "./Player.js";

type GameCtx = ICtx<GameState, IPhysicsContext>;

const PATROL_SPEED = 2.8;
const CHASE_SPEED = 3.5;
const SCAN_RADIUS = 8;
const FIRE_RANGE = 15;

export class Rifleman {
  readonly mesh: Group;
  readonly body: RigidBody3D;
  readonly tags = ["hostile", "rifleman"];
  readonly wave: number | undefined;
  health: number;
  alive = true;
  acquired = false;
  #scanHandle: ScheduleHandle | undefined;
  #fireTimer = 0;
  #scanShape = CollisionShape3D.sphere(SCAN_RADIUS);
  #velocity = new Vector3(0, 0, 0);
  #patrolWaypoints: Vector3[];
  #currentWaypointIndex = 0;
  #onFire: (origin: Vector3) => void;

  constructor(
    ctx: GameCtx,
    materials: Parameters<typeof createRiflemanVisual>[0],
    position: Vector3,
    patrolWaypoints: Vector3[],
    options: {
      readonly health?: number;
      readonly onFire?: (origin: Vector3) => void;
      readonly wave?: number;
    } = {},
  ) {
    this.wave = options.wave;
    this.health = options.health ?? 50;
    this.#onFire = options.onFire ?? (() => undefined);
    this.#patrolWaypoints = patrolWaypoints.length > 0 ? patrolWaypoints : [position.clone()];
    this.mesh = createRiflemanVisual(materials);
    this.mesh.position.copy(position);
    ctx.add(this.mesh);
    this.body = new RigidBody3D({
      collisionLayer: HOSTILE_LAYER,
      collisionMask: WORLD_LAYER,
      object: this.mesh,
      physics: ctx.physics,
      shape: CollisionShape3D.box(0.8, 1.8, 0.8),
      type: "kinematic",
    });
  }

  startScanning(ctx: GameCtx, playerBodyId: number): void {
    const scan = (): void => {
      if (!this.alive) return;
      const hits = directSpaceState(ctx.physics).intersectShape({
        collisionMask: PLAYER_LAYER,
        maxResults: 4,
        position: this.mesh.position,
        shape: this.#scanShape,
      });
      this.acquired = hits.some((hit) => hit.body.id === playerBodyId);
      this.#scanHandle = ctx.after(ctx.random.range(3, 8) / 60, scan);
    };
    this.#scanHandle = ctx.after(ctx.random.range(3, 8) / 60, scan);
  }

  update(ctx: GameCtx, dt: number, playerPos: Vector3): void {
    if (!this.alive) return;

    if (this.acquired) {
      this.#updateChase(playerPos, dt);
      this.#updateFire(playerPos, dt);
    } else {
      this.#updatePatrol(dt);
    }

    this.body.velocity.copy(this.#velocity);
    this.body.velocity.y = 0;
    const before = this.mesh.position.clone();
    this.body.moveAndSlide(dt);
    this.mesh.position.y = before.y;
  }

  #updatePatrol(dt: number): void {
    const current = this.#patrolWaypoints[this.#currentWaypointIndex];
    if (current === undefined) return;

    const direction = current.clone().sub(this.mesh.position);
    const distToWaypoint = direction.length();

    if (distToWaypoint < 0.5) {
      this.#currentWaypointIndex = (this.#currentWaypointIndex + 1) % this.#patrolWaypoints.length;
      this.#velocity.set(0, 0, 0);
    } else {
      direction.normalize().multiplyScalar(PATROL_SPEED);
      this.#velocity.copy(direction);
